import csv
import io
import re


def parse_csv(raw_csv: str):
    expected_width = 8
    if raw_csv.startswith("\ufeff"):
        raw_csv = raw_csv[1:]

    records = list(
        csv.reader(
            io.StringIO(raw_csv, newline=""),
            delimiter=";",
            quotechar='"',
            doublequote=True,
            strict=False,
        )
    )

    first_nonblank = None
    first_full_width = None
    first_text_header = None
    header_index = None

    for i, row in enumerate(records):
        if not any(cell.strip() for cell in row):
            continue
        if first_nonblank is None:
            first_nonblank = i
        if len(row) != expected_width:
            continue
        if first_full_width is None:
            first_full_width = i

        labels = [cell.strip() for cell in row[1:]]
        if not row[0].strip() and all(
            re.fullmatch(r"[A-Za-z_][A-Za-z0-9_]*", label) for label in labels
        ):
            header_index = i
            break
        if first_text_header is None and all(
            any(char.isalpha() for char in label) for label in labels
        ):
            first_text_header = i

    if header_index is None:
        header_index = next(
            (
                index
                for index in (first_text_header, first_full_width, first_nonblank)
                if index is not None
            ),
            None,
        )
    if header_index is None:
        return {"columns": [], "rows": []}

    columns = records[header_index].copy()
    rows = records[header_index + 1:]
    width = max(expected_width, len(columns), max(map(len, rows), default=0))

    used_names = set(columns)
    for position in range(len(columns) + 1, width + 1):
        name = f"extra_{position}"
        while name in used_names:
            name += "_"
        columns.append(name)
        used_names.add(name)

    return {
        "columns": columns,
        "rows": [row + [""] * (width - len(row)) for row in rows],
    }
